84-    });
85-    const keptNames = new Set(kept.map((tool) => tool.name));
86-    const added = desired.filter((tool) => !keptNames.has(tool.name));
87-    const replayed = [...kept, ...added];
88-    if (replayed.some((tool, index) => tool.name !== desired[index].name)) {
89-        return {
