91-            toolsAdded: desired.map(toToolDeclaration),
92-        };
93-    }
94-    return {
95-        toolsRemoved: offered.filter((tool) => !keptNames.has(tool.name)).map((tool) => ({ name: tool.name })),
96-        toolsAdded: added.map(toToolDeclaration),
97-    };
98-}
99-/** Section patches: none, the minimal patch, or a remove-all/re-add-all pair when the order would differ. */
100-function planSections(shown, desired) {
101-    const patchedOrder = [
102-        ...[...shown.keys()].filter((key) => desired.has(key)),
103-        ...[...desired.keys()].filter((key) => !shown.has(key)),
104-    ];
105-    const desiredOrder = [...desired.keys()];
106-    if (patchedOrder.some((key, index) => key !== desiredOrder[index])) {
107-        return [Object.fromEntries([...shown.keys()].map((key) => [key, null])), Object.fromEntries(desired)];
108-    }
109-    const patch = {};
110-    for (const [key, value] of shown) {
111-        const next = desired.get(key);
112-        if (next !== value)
113-            patch[key] = next ?? null;
114-    }
115-    for (const [key, value] of desired)
116-        if (!shown.has(key))
117-            patch[key] = value;
118-    return Object.keys(patch).length === 0 ? [] : [patch];
